const ramakathaHindiDigits='०१२३४५६७८९'; for(let i=2;i<=19;i++) window.RAMAKATHA_HINDI[i].title=window.RAMAKATHA_HINDI[i].title.replace(/भाग १ · अध्याय ([०-९]+)/,(m,n)=>'भाग १ · अध्याय '+String(Number([...n].map(d=>ramakathaHindiDigits.indexOf(d)).join(''))+1).replace(/\d/g,d=>ramakathaHindiDigits[d]));
